inline void VoxRlEncodeRevealedOverrideRecord(const RevealedOverrideRecord& record, u8* bytes)
{
    VoxRlZeroBytes(bytes, kVoxRlWireSizeRevealedOverrideRecord);
    bytes[0] = static_cast<u8>(record.team);
    const u32 packedplotIndex = static_cast<u32>(record.plotIndex);
    bytes[1] = static_cast<u8>(packedplotIndex);
    bytes[2] = static_cast<u8>(packedplotIndex >> 8);
    bytes[3] = static_cast<u8>(record.revealedImprovementType);
    bytes[4] = static_cast<u8>(record.revealedRouteType);
    bytes[5] = static_cast<u8>(record.revealedOwner);
}

// Decodes one RevealedOverrideRecord from exactly 6 little-endian wire bytes.
inline void VoxRlDecodeRevealedOverrideRecord(const u8* bytes, RevealedOverrideRecord& record)
{
    record.team = static_cast<i8>(bytes[0]);
    record.plotIndex = static_cast<i16>(static_cast<u32>(bytes[1]) | (static_cast<u32>(bytes[2]) << 8));
    record.revealedImprovementType = static_cast<i8>(bytes[3]);
    record.revealedRouteType = static_cast<i8>(bytes[4]);
    record.revealedOwner = static_cast<i8>(bytes[5]);
}

// Generic dense wire codec entry points for RevealedOverrideRecord.
template <> inline void VoxRlEncodeWire<RevealedOverrideRecord>(const RevealedOverrideRecord& record, u8* bytes) { VoxRlEncodeRevealedOverrideRecord(record, bytes); }
template <> inline void VoxRlDecodeWire<RevealedOverrideRecord>(const u8* bytes, RevealedOverrideRecord& record) { VoxRlDecodeRevealedOverrideRecord(bytes, record); }
